// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address expectedOwner;

    function setUp() public {
        c = new C();
        Initializer init = new Initializer();
        init.doInit(c);
        expectedOwner = address(init);
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // RULE: for ANY caller, c.owner() returns the stored owner (the initializer),
        // independent of msg.sender.
        vm.prank(actor);
        assertTrue(c.owner() == expectedOwner);
    }
}

contract Initializer {
    address public protocolFeeDestination;

    constructor() {
        protocolFeeDestination = address(this);
    }

    function doInit(C c) external {
        c.initialize(1, 1, "v", address(this));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor1, address actor2) public {
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor1 != actor2);

        vm.prank(actor1);
        address observed1 = c.owner();
        vm.prank(actor2);
        address observed2 = c.owner();

        // General rule: owner() is caller-independent — every caller observes the same owner value.
        assertTrue(observed1 == observed2);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address newOwner) public {
        // admissible: the pending owner must be a real, nonzero address
        vm.assume(newOwner != address(0));

        // current owner is the zero address (never initialized), so a call from
        // address(0) passes the onlyOwner check and starts the 2-step transfer
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // the designated pending owner accepts ownership
        vm.prank(newOwner);
        c.acceptOwnership();

        // General rule: after a successful two-step ownership transfer to any
        // nonzero address, owner() reports exactly that address.
        assertTrue(c.owner() == newOwner);
    }
}
